INSERT INTO "traducao" ("id", "idioma", "hash_origem", "texto") VALUES
  (gen_random_uuid()::text, 'en', '218c160a4134054c', 'The Ferramenta UEQ has a new version live'),
  (gen_random_uuid()::text, 'es', '218c160a4134054c', 'La Ferramenta UEQ tiene una nueva versión disponible'),
  (gen_random_uuid()::text, 'de', '218c160a4134054c', 'Die Ferramenta UEQ hat eine neue Version'),
  (gen_random_uuid()::text, 'fr', '218c160a4134054c', 'La Ferramenta UEQ a une nouvelle version en ligne'),
  (gen_random_uuid()::text, 'it', '218c160a4134054c', 'La Ferramenta UEQ ha una nuova versione online'),
  (gen_random_uuid()::text, 'nl', '218c160a4134054c', 'De Ferramenta UEQ heeft een nieuwe versie online'),
  (gen_random_uuid()::text, 'da', '218c160a4134054c', 'Ferramenta UEQ har en ny version online'),
  (gen_random_uuid()::text, 'sv', '218c160a4134054c', 'Ferramenta UEQ har en ny version ute'),
  (gen_random_uuid()::text, 'nb', '218c160a4134054c', 'Ferramenta UEQ har en ny versjon ute'),
  (gen_random_uuid()::text, 'fi', '218c160a4134054c', 'Ferramenta UEQ:sta on uusi versio käytössä'),
  (gen_random_uuid()::text, 'et', '218c160a4134054c', 'Ferramenta UEQ uus versioon on üleval'),
  (gen_random_uuid()::text, 'pl', '218c160a4134054c', 'Ferramenta UEQ ma nową wersję'),
  (gen_random_uuid()::text, 'cs', '218c160a4134054c', 'Ferramenta UEQ má novou verzi'),
  (gen_random_uuid()::text, 'sk', '218c160a4134054c', 'Ferramenta UEQ má novú verziu'),
  (gen_random_uuid()::text, 'sl', '218c160a4134054c', 'Ferramenta UEQ ima novo različico'),
  (gen_random_uuid()::text, 'hr', '218c160a4134054c', 'Ferramenta UEQ ima novu verziju'),
  (gen_random_uuid()::text, 'bs', '218c160a4134054c', 'Ferramenta UEQ ima novu verziju'),
  (gen_random_uuid()::text, 'hu', '218c160a4134054c', 'A Ferramenta UEQ új verziója elérhető'),
  (gen_random_uuid()::text, 'bg', '218c160a4134054c', 'Ferramenta UEQ има нова версия'),
  (gen_random_uuid()::text, 'ru', '218c160a4134054c', 'У Ferramenta UEQ новая версия'),
  (gen_random_uuid()::text, 'el', '218c160a4134054c', 'Το Ferramenta UEQ έχει νέα έκδοση'),
  (gen_random_uuid()::text, 'tr', '218c160a4134054c', 'Ferramenta UEQ''nun yeni sürümü yayında'),
  (gen_random_uuid()::text, 'ar', '218c160a4134054c', 'إصدار جديد من Ferramenta UEQ متاح الآن'),
  (gen_random_uuid()::text, 'he', '218c160a4134054c', 'גרסה חדשה של Ferramenta UEQ זמינה'),
  (gen_random_uuid()::text, 'fa', '218c160a4134054c', 'نسخهٔ جدید Ferramenta UEQ منتشر شد'),
  (gen_random_uuid()::text, 'hi', '218c160a4134054c', 'Ferramenta UEQ का नया संस्करण उपलब्ध है'),
  (gen_random_uuid()::text, 'mr', '218c160a4134054c', 'Ferramenta UEQ ची नवी आवृत्ती उपलब्ध आहे'),
  (gen_random_uuid()::text, 'bn', '218c160a4134054c', 'Ferramenta UEQ-এর নতুন সংস্করণ চালু হয়েছে'),
  (gen_random_uuid()::text, 'ta', '218c160a4134054c', 'Ferramenta UEQ-இன் புதிய பதிப்பு வெளியாகியுள்ளது'),
  (gen_random_uuid()::text, 'kn', '218c160a4134054c', 'Ferramenta UEQ ಹೊಸ ಆವೃತ್ತಿ ಲಭ್ಯವಿದೆ'),
  (gen_random_uuid()::text, 'th', '218c160a4134054c', 'Ferramenta UEQ มีเวอร์ชันใหม่แล้ว'),
  (gen_random_uuid()::text, 'ms', '218c160a4134054c', 'Ferramenta UEQ mempunyai versi baharu'),
  (gen_random_uuid()::text, 'id', '218c160a4134054c', 'Ferramenta UEQ punya versi baru'),
  (gen_random_uuid()::text, 'zh', '218c160a4134054c', 'Ferramenta UEQ 发布了新版本'),
  (gen_random_uuid()::text, 'ja', '218c160a4134054c', 'Ferramenta UEQ の新しいバージョンを公開しました'),
  (gen_random_uuid()::text, 'ko', '218c160a4134054c', 'Ferramenta UEQ 새 버전이 나왔습니다'),
  (gen_random_uuid()::text, 'en', 'd0f00fd43ea72bb4', 'The official spreadsheet now comes with the results, the tool tells you when something is loading, and emails are back.'),
  (gen_random_uuid()::text, 'es', 'd0f00fd43ea72bb4', 'La planilla oficial ya sale con los resultados, la herramienta avisa cuando algo está cargando y los correos volvieron.'),
  (gen_random_uuid()::text, 'de', 'd0f00fd43ea72bb4', 'Die offizielle Tabelle enthält jetzt die Ergebnisse, das Tool zeigt an, wenn etwas lädt, und E-Mails kommen wieder an.'),
  (gen_random_uuid()::text, 'fr', 'd0f00fd43ea72bb4', 'Le tableur officiel sort maintenant avec les résultats, l’outil indique quand quelque chose se charge et les e-mails sont de retour.'),
  (gen_random_uuid()::text, 'it', 'd0f00fd43ea72bb4', 'Il foglio ufficiale ora esce con i risultati, lo strumento avvisa quando qualcosa si sta caricando e le e-mail sono tornate.'),
  (gen_random_uuid()::text, 'nl', 'd0f00fd43ea72bb4', 'Het officiële werkblad komt nu met de resultaten, de tool laat zien wanneer iets laadt en de e-mails zijn terug.'),
  (gen_random_uuid()::text, 'da', 'd0f00fd43ea72bb4', 'Det officielle regneark kommer nu med resultaterne, værktøjet viser, når noget indlæses, og e-mailene er tilbage.'),
  (gen_random_uuid()::text, 'sv', 'd0f00fd43ea72bb4', 'Det officiella kalkylbladet kommer nu med resultaten, verktyget visar när något laddas och e-posten fungerar igen.'),
  (gen_random_uuid()::text, 'nb', 'd0f00fd43ea72bb4', 'Det offisielle regnearket kommer nå med resultatene, verktøyet viser når noe lastes inn, og e-postene er tilbake.'),
  (gen_random_uuid()::text, 'fi', 'd0f00fd43ea72bb4', 'Virallinen laskentataulukko sisältää nyt tulokset, työkalu kertoo, kun jotain latautuu, ja sähköpostit toimivat taas.'),
  (gen_random_uuid()::text, 'et', 'd0f00fd43ea72bb4', 'Ametlik tabel tuleb nüüd tulemustega, tööriist näitab, kui midagi laaditakse, ja e-kirjad töötavad jälle.'),
  (gen_random_uuid()::text, 'pl', 'd0f00fd43ea72bb4', 'Oficjalny arkusz zawiera już wyniki, narzędzie pokazuje, kiedy coś się wczytuje, a e-maile znowu działają.'),
  (gen_random_uuid()::text, 'cs', 'd0f00fd43ea72bb4', 'Oficiální tabulka už obsahuje výsledky, nástroj ukazuje, když se něco načítá, a e-maily zase chodí.'),
  (gen_random_uuid()::text, 'sk', 'd0f00fd43ea72bb4', 'Oficiálna tabuľka už obsahuje výsledky, nástroj ukazuje, keď sa niečo načítava, a e-maily znova chodia.'),
  (gen_random_uuid()::text, 'sl', 'd0f00fd43ea72bb4', 'Uradna preglednica zdaj vsebuje rezultate, orodje pokaže, ko se kaj nalaga, e-pošta pa spet deluje.'),
  (gen_random_uuid()::text, 'hr', 'd0f00fd43ea72bb4', 'Službena tablica sada dolazi s rezultatima, alat pokazuje kad se nešto učitava, a e-pošta opet radi.'),
  (gen_random_uuid()::text, 'bs', 'd0f00fd43ea72bb4', 'Zvanična tabela sada dolazi s rezultatima, alat pokazuje kad se nešto učitava, a e-pošta opet radi.'),
  (gen_random_uuid()::text, 'hu', 'd0f00fd43ea72bb4', 'A hivatalos táblázat már az eredményekkel együtt készül, az eszköz jelzi, ha valami töltődik, és az e-mailek újra mennek.'),
  (gen_random_uuid()::text, 'bg', 'd0f00fd43ea72bb4', 'Официалната таблица вече излиза с резултатите, инструментът показва, когато нещо се зарежда, и имейлите отново работят.'),
  (gen_random_uuid()::text, 'ru', 'd0f00fd43ea72bb4', 'Официальная таблица теперь выходит с результатами, инструмент показывает, когда что-то загружается, и письма снова приходят.'),
  (gen_random_uuid()::text, 'el', 'd0f00fd43ea72bb4', 'Το επίσημο υπολογιστικό φύλλο βγαίνει πια με τα αποτελέσματα, το εργαλείο δείχνει πότε κάτι φορτώνει και τα email λειτουργούν ξανά.'),
  (gen_random_uuid()::text, 'tr', 'd0f00fd43ea72bb4', 'Resmî tablo artık sonuçlarla birlikte geliyor, araç bir şey yüklenirken haber veriyor ve e-postalar yeniden çalışıyor.'),
  (gen_random_uuid()::text, 'ar', 'd0f00fd43ea72bb4', 'أصبح الجدول الرسمي يخرج مع النتائج، وتنبّه الأداة عندما يكون شيء ما قيد التحميل، وعادت رسائل البريد الإلكتروني.'),
  (gen_random_uuid()::text, 'he', 'd0f00fd43ea72bb4', 'הגיליון הרשמי יוצא עכשיו עם התוצאות, הכלי מראה מתי משהו נטען, והמיילים חזרו.'),
  (gen_random_uuid()::text, 'fa', 'd0f00fd43ea72bb4', 'جدول رسمی حالا با نتایج بیرون می‌آید، ابزار وقتی چیزی در حال بارگذاری است خبر می‌دهد و ایمیل‌ها دوباره کار می‌کنند.'),
  (gen_random_uuid()::text, 'hi', 'd0f00fd43ea72bb4', 'आधिकारिक स्प्रेडशीट अब नतीजों के साथ आती है, टूल बताता है कि कब कुछ लोड हो रहा है, और ईमेल फिर से आने लगे हैं।'),
  (gen_random_uuid()::text, 'mr', 'd0f00fd43ea72bb4', 'अधिकृत स्प्रेडशीट आता निकालांसह येते, काही लोड होत असताना टूल सांगते आणि ईमेल पुन्हा येऊ लागले आहेत.'),
  (gen_random_uuid()::text, 'bn', 'd0f00fd43ea72bb4', 'অফিসিয়াল স্প্রেডশিট এখন ফলাফলসহ আসে, কিছু লোড হলে টুল জানায়, আর ইমেল আবার আসছে।'),
  (gen_random_uuid()::text, 'ta', 'd0f00fd43ea72bb4', 'அதிகாரப்பூர்வ விரிதாள் இப்போது முடிவுகளுடன் வருகிறது, ஏதாவது ஏற்றப்படும்போது கருவி தெரிவிக்கிறது, மின்னஞ்சல்களும் மீண்டும் வருகின்றன.'),
  (gen_random_uuid()::text, 'kn', 'd0f00fd43ea72bb4', 'ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಈಗ ಫಲಿತಾಂಶಗಳೊಂದಿಗೆ ಬರುತ್ತದೆ, ಏನಾದರೂ ಲೋಡ್ ಆಗುತ್ತಿದ್ದಾಗ ಸಾಧನ ತಿಳಿಸುತ್ತದೆ, ಮತ್ತು ಇಮೇಲ್‌ಗಳು ಮತ್ತೆ ಬರುತ್ತಿವೆ.'),
  (gen_random_uuid()::text, 'th', 'd0f00fd43ea72bb4', 'สเปรดชีตทางการมาพร้อมผลลัพธ์แล้ว เครื่องมือจะแจ้งเมื่อมีอะไรกำลังโหลด และอีเมลกลับมาใช้ได้แล้ว'),
  (gen_random_uuid()::text, 'ms', 'd0f00fd43ea72bb4', 'Hamparan rasmi kini disertakan dengan keputusan, alat ini memberitahu apabila sesuatu sedang dimuatkan, dan e-mel berfungsi semula.'),
  (gen_random_uuid()::text, 'id', 'd0f00fd43ea72bb4', 'Spreadsheet resmi kini keluar dengan hasilnya, alat ini memberi tahu saat sesuatu sedang dimuat, dan email sudah kembali.'),
  (gen_random_uuid()::text, 'zh', 'd0f00fd43ea72bb4', '官方表格现在会带着结果导出，工具会提示正在加载的内容，邮件也恢复了。'),
  (gen_random_uuid()::text, 'ja', 'd0f00fd43ea72bb4', '公式スプレッドシートに結果が入るようになり、読み込み中であることをツールが知らせ、メールも再び届くようになりました。'),
  (gen_random_uuid()::text, 'ko', 'd0f00fd43ea72bb4', '공식 스프레드시트에 이제 결과가 들어 있고, 무언가를 불러오는 중이면 도구가 알려 주며, 이메일도 다시 옵니다.'),
  (gen_random_uuid()::text, 'en', '17b959119c0280ca', 'Hello! We have published a new version of the tool, with these fixes:'),
  (gen_random_uuid()::text, 'es', '17b959119c0280ca', '¡Hola! Publicamos una nueva versión de la herramienta, con estas correcciones:'),
  (gen_random_uuid()::text, 'de', '17b959119c0280ca', 'Hallo! Wir haben eine neue Version des Tools veröffentlicht, mit diesen Korrekturen:'),
  (gen_random_uuid()::text, 'fr', '17b959119c0280ca', 'Bonjour ! Nous avons publié une nouvelle version de l’outil, avec ces corrections :'),
  (gen_random_uuid()::text, 'it', '17b959119c0280ca', 'Salve! Abbiamo pubblicato una nuova versione dello strumento, con queste correzioni:'),
  (gen_random_uuid()::text, 'nl', '17b959119c0280ca', 'Hallo! We hebben een nieuwe versie van de tool gepubliceerd, met deze correcties:'),
  (gen_random_uuid()::text, 'da', '17b959119c0280ca', 'Hej! Vi har udgivet en ny version af værktøjet med disse rettelser:'),
  (gen_random_uuid()::text, 'sv', '17b959119c0280ca', 'Hej! Vi har publicerat en ny version av verktyget, med de här rättelserna:'),
  (gen_random_uuid()::text, 'nb', '17b959119c0280ca', 'Hei! Vi har publisert en ny versjon av verktøyet, med disse rettelsene:'),
  (gen_random_uuid()::text, 'fi', '17b959119c0280ca', 'Hei! Julkaisimme työkalusta uuden version, jossa on nämä korjaukset:'),
  (gen_random_uuid()::text, 'et', '17b959119c0280ca', 'Tere! Avaldasime tööriista uue versiooni, kus on need parandused:'),
  (gen_random_uuid()::text, 'pl', '17b959119c0280ca', 'Dzień dobry! Opublikowaliśmy nową wersję narzędzia z tymi poprawkami:'),
  (gen_random_uuid()::text, 'cs', '17b959119c0280ca', 'Dobrý den! Zveřejnili jsme novou verzi nástroje s těmito opravami:'),
  (gen_random_uuid()::text, 'sk', '17b959119c0280ca', 'Dobrý deň! Zverejnili sme novú verziu nástroja s týmito opravami:'),
  (gen_random_uuid()::text, 'sl', '17b959119c0280ca', 'Pozdravljeni! Objavili smo novo različico orodja s temi popravki:'),
  (gen_random_uuid()::text, 'hr', '17b959119c0280ca', 'Pozdrav! Objavili smo novu verziju alata s ovim ispravcima:'),
  (gen_random_uuid()::text, 'bs', '17b959119c0280ca', 'Zdravo! Objavili smo novu verziju alata s ovim ispravkama:'),
  (gen_random_uuid()::text, 'hu', '17b959119c0280ca', 'Üdvözöljük! Közzétettük az eszköz új verzióját, ezekkel a javításokkal:'),
  (gen_random_uuid()::text, 'bg', '17b959119c0280ca', 'Здравейте! Публикувахме нова версия на инструмента с тези корекции:'),
  (gen_random_uuid()::text, 'ru', '17b959119c0280ca', 'Здравствуйте! Мы опубликовали новую версию инструмента с такими исправлениями:'),
  (gen_random_uuid()::text, 'el', '17b959119c0280ca', 'Γεια σας! Δημοσιεύσαμε νέα έκδοση του εργαλείου, με αυτές τις διορθώσεις:'),
  (gen_random_uuid()::text, 'tr', '17b959119c0280ca', 'Merhaba! Aracın yeni bir sürümünü şu düzeltmelerle yayımladık:'),
  (gen_random_uuid()::text, 'ar', '17b959119c0280ca', 'مرحبًا! نشرنا إصدارًا جديدًا من الأداة، مع هذه التصحيحات:'),
  (gen_random_uuid()::text, 'he', '17b959119c0280ca', 'שלום! פרסמנו גרסה חדשה של הכלי, עם התיקונים האלה:'),
  (gen_random_uuid()::text, 'fa', '17b959119c0280ca', 'سلام! نسخهٔ جدیدی از ابزار را با این اصلاحات منتشر کردیم:'),
  (gen_random_uuid()::text, 'hi', '17b959119c0280ca', 'नमस्ते! हमने टूल का नया संस्करण इन सुधारों के साथ प्रकाशित किया है:'),
  (gen_random_uuid()::text, 'mr', '17b959119c0280ca', 'नमस्कार! आम्ही टूलची नवी आवृत्ती या दुरुस्त्यांसह प्रकाशित केली आहे:'),
  (gen_random_uuid()::text, 'bn', '17b959119c0280ca', 'নমস্কার! আমরা এই সংশোধনগুলোসহ টুলের নতুন সংস্করণ প্রকাশ করেছি:'),
  (gen_random_uuid()::text, 'ta', '17b959119c0280ca', 'வணக்கம்! இந்தத் திருத்தங்களுடன் கருவியின் புதிய பதிப்பை வெளியிட்டுள்ளோம்:'),
  (gen_random_uuid()::text, 'kn', '17b959119c0280ca', 'ನಮಸ್ಕಾರ! ಈ ತಿದ್ದುಪಡಿಗಳೊಂದಿಗೆ ಸಾಧನದ ಹೊಸ ಆವೃತ್ತಿಯನ್ನು ಪ್ರಕಟಿಸಿದ್ದೇವೆ:'),
  (gen_random_uuid()::text, 'th', '17b959119c0280ca', 'สวัสดี! เราเผยแพร่เครื่องมือเวอร์ชันใหม่พร้อมการแก้ไขเหล่านี้:'),
  (gen_random_uuid()::text, 'ms', '17b959119c0280ca', 'Helo! Kami telah menerbitkan versi baharu alat ini dengan pembetulan berikut:'),
  (gen_random_uuid()::text, 'id', '17b959119c0280ca', 'Halo! Kami telah merilis versi baru alat ini dengan perbaikan berikut:'),
  (gen_random_uuid()::text, 'zh', '17b959119c0280ca', '您好！我们发布了工具的新版本，包含以下修正：'),
  (gen_random_uuid()::text, 'ja', '17b959119c0280ca', 'こんにちは。次の修正を含む新しいバージョンのツールを公開しました。'),
  (gen_random_uuid()::text, 'ko', '17b959119c0280ca', '안녕하세요! 다음 수정 사항을 담은 도구의 새 버전을 게시했습니다.'),
  (gen_random_uuid()::text, 'en', 'a57a2293684747da', 'The exported official UEQ and UEQ-S spreadsheet now comes with all results calculated and the charts filled in, even in Excel''s Protected View.'),
  (gen_random_uuid()::text, 'es', 'a57a2293684747da', 'La planilla oficial del UEQ y del UEQ-S exportada ya sale con todos los resultados calculados y los gráficos completos, incluso en la Vista protegida de Excel.'),
  (gen_random_uuid()::text, 'de', 'a57a2293684747da', 'Die exportierte offizielle Tabelle für UEQ und UEQ-S enthält jetzt alle berechneten Ergebnisse und ausgefüllten Diagramme, auch in der Geschützten Ansicht von Excel.'),
  (gen_random_uuid()::text, 'fr', 'a57a2293684747da', 'Le tableur officiel UEQ et UEQ-S exporté sort maintenant avec tous les résultats calculés et les graphiques remplis, même en Mode protégé d’Excel.'),
  (gen_random_uuid()::text, 'it', 'a57a2293684747da', 'Il foglio ufficiale UEQ e UEQ-S esportato ora esce con tutti i risultati calcolati e i grafici compilati, anche nella Visualizzazione protetta di Excel.'),
  (gen_random_uuid()::text, 'nl', 'a57a2293684747da', 'Het geëxporteerde officiële UEQ- en UEQ-S-werkblad komt nu met alle resultaten berekend en de grafieken ingevuld, ook in de Beveiligde weergave van Excel.'),
  (gen_random_uuid()::text, 'da', 'a57a2293684747da', 'Det eksporterede officielle regneark for UEQ og UEQ-S kommer nu med alle resultater beregnet og diagrammerne udfyldt, også i Beskyttet visning i Excel.'),
  (gen_random_uuid()::text, 'sv', 'a57a2293684747da', 'Det exporterade officiella kalkylbladet för UEQ och UEQ-S kommer nu med alla resultat beräknade och diagrammen ifyllda, även i Skyddad vy i Excel.'),
  (gen_random_uuid()::text, 'nb', 'a57a2293684747da', 'Det eksporterte offisielle regnearket for UEQ og UEQ-S kommer nå med alle resultater beregnet og diagrammene fylt ut, også i Beskyttet visning i Excel.'),
  (gen_random_uuid()::text, 'fi', 'a57a2293684747da', 'Viety virallinen UEQ- ja UEQ-S-laskentataulukko sisältää nyt kaikki lasketut tulokset ja täytetyt kaaviot, myös Excelin suojatussa näkymässä.'),
  (gen_random_uuid()::text, 'et', 'a57a2293684747da', 'Eksporditud ametlik UEQ ja UEQ-S tabel tuleb nüüd kõigi arvutatud tulemuste ja täidetud diagrammidega, ka Exceli kaitstud vaates.'),
  (gen_random_uuid()::text, 'pl', 'a57a2293684747da', 'Eksportowany oficjalny arkusz UEQ i UEQ-S zawiera już wszystkie obliczone wyniki i wypełnione wykresy, także w Widoku chronionym Excela.'),
  (gen_random_uuid()::text, 'cs', 'a57a2293684747da', 'Exportovaná oficiální tabulka UEQ a UEQ-S už obsahuje všechny vypočtené výsledky a vyplněné grafy, i v Chráněném zobrazení Excelu.'),
  (gen_random_uuid()::text, 'sk', 'a57a2293684747da', 'Exportovaná oficiálna tabuľka UEQ a UEQ-S už obsahuje všetky vypočítané výsledky a vyplnené grafy, aj v Chránenom zobrazení Excelu.'),
  (gen_random_uuid()::text, 'sl', 'a57a2293684747da', 'Izvožena uradna preglednica UEQ in UEQ-S zdaj vsebuje vse izračunane rezultate in izpolnjene grafe, tudi v Zaščitenem pogledu Excela.'),
  (gen_random_uuid()::text, 'hr', 'a57a2293684747da', 'Izvezena službena tablica UEQ i UEQ-S sada dolazi sa svim izračunatim rezultatima i popunjenim grafikonima, i u Zaštićenom prikazu Excela.'),
  (gen_random_uuid()::text, 'bs', 'a57a2293684747da', 'Izvezena zvanična tabela UEQ i UEQ-S sada dolazi sa svim izračunatim rezultatima i popunjenim grafikonima, i u Zaštićenom prikazu Excela.'),
  (gen_random_uuid()::text, 'hu', 'a57a2293684747da', 'Az exportált hivatalos UEQ- és UEQ-S-táblázat már minden kiszámított eredménnyel és kitöltött diagrammal készül, az Excel Védett nézetében is.'),
  (gen_random_uuid()::text, 'bg', 'a57a2293684747da', 'Експортираната официална таблица за UEQ и UEQ-S вече излиза с всички изчислени резултати и попълнени диаграми, дори в Защитен изглед на Excel.'),
  (gen_random_uuid()::text, 'ru', 'a57a2293684747da', 'Экспортированная официальная таблица UEQ и UEQ-S теперь выходит со всеми рассчитанными результатами и заполненными диаграммами, даже в режиме защищённого просмотра Excel.'),
  (gen_random_uuid()::text, 'el', 'a57a2293684747da', 'Το εξαγόμενο επίσημο υπολογιστικό φύλλο UEQ και UEQ-S βγαίνει πια με όλα τα αποτελέσματα υπολογισμένα και τα γραφήματα συμπληρωμένα, ακόμη και στην Προστατευμένη προβολή του Excel.'),
  (gen_random_uuid()::text, 'tr', 'a57a2293684747da', 'Dışa aktarılan resmî UEQ ve UEQ-S tablosu artık tüm sonuçlar hesaplanmış ve grafikler doldurulmuş olarak geliyor, Excel''in Korumalı Görünüm''ünde bile.'),
  (gen_random_uuid()::text, 'ar', 'a57a2293684747da', 'أصبح الجدول الرسمي المُصدَّر لـ UEQ وUEQ-S يخرج بكل النتائج محسوبة والرسوم البيانية مكتملة، حتى في طريقة العرض المحمية في Excel.'),
  (gen_random_uuid()::text, 'he', 'a57a2293684747da', 'הגיליון הרשמי של UEQ ושל UEQ-S שמיוצא יוצא עכשיו עם כל התוצאות מחושבות והתרשימים מלאים, גם בתצוגה מוגנת של Excel.'),
  (gen_random_uuid()::text, 'fa', 'a57a2293684747da', 'جدول رسمی UEQ و UEQ-S که خروجی گرفته می‌شود حالا با همهٔ نتایج محاسبه‌شده و نمودارهای پرشده بیرون می‌آید، حتی در نمای محافظت‌شدهٔ Excel.'),
  (gen_random_uuid()::text, 'hi', 'a57a2293684747da', 'निर्यात की गई UEQ और UEQ-S की आधिकारिक स्प्रेडशीट अब सभी गणना किए गए नतीजों और भरे हुए चार्ट के साथ आती है, Excel के संरक्षित दृश्य में भी।'),
  (gen_random_uuid()::text, 'mr', 'a57a2293684747da', 'निर्यात केलेली UEQ आणि UEQ-S ची अधिकृत स्प्रेडशीट आता सर्व गणना केलेल्या निकालांसह आणि भरलेल्या तक्त्यांसह येते, Excel च्या संरक्षित दृश्यातही.'),
  (gen_random_uuid()::text, 'bn', 'a57a2293684747da', 'এক্সপোর্ট করা UEQ ও UEQ-S-এর অফিসিয়াল স্প্রেডশিট এখন সব হিসাব করা ফলাফল আর পূরণ করা চার্টসহ আসে, Excel-এর সুরক্ষিত দৃশ্যেও।'),
  (gen_random_uuid()::text, 'ta', 'a57a2293684747da', 'ஏற்றுமதி செய்யப்படும் UEQ, UEQ-S அதிகாரப்பூர்வ விரிதாள் இப்போது கணக்கிடப்பட்ட எல்லா முடிவுகளுடனும் நிரப்பப்பட்ட வரைபடங்களுடனும் வருகிறது, Excel-இன் பாதுகாக்கப்பட்ட காட்சியிலும்.'),
  (gen_random_uuid()::text, 'kn', 'a57a2293684747da', 'ರಫ್ತು ಮಾಡಿದ UEQ ಮತ್ತು UEQ-S ಅಧಿಕೃತ ಸ್ಪ್ರೆಡ್‌ಶೀಟ್ ಈಗ ಲೆಕ್ಕ ಹಾಕಿದ ಎಲ್ಲ ಫಲಿತಾಂಶಗಳು ಮತ್ತು ತುಂಬಿದ ಚಾರ್ಟ್‌ಗಳೊಂದಿಗೆ ಬರುತ್ತದೆ, Excel‌ನ ಸಂರಕ್ಷಿತ ವೀಕ್ಷಣೆಯಲ್ಲೂ.'),
  (gen_random_uuid()::text, 'th', 'a57a2293684747da', 'สเปรดชีตทางการของ UEQ และ UEQ-S ที่ส่งออกมาพร้อมผลลัพธ์ที่คำนวณครบและแผนภูมิที่เติมแล้ว แม้ในมุมมองที่ได้รับการป้องกันของ Excel'),
  (gen_random_uuid()::text, 'ms', 'a57a2293684747da', 'Hamparan rasmi UEQ dan UEQ-S yang dieksport kini disertakan dengan semua keputusan yang dikira dan carta yang diisi, malah dalam Paparan Dilindungi Excel.'),
  (gen_random_uuid()::text, 'id', 'a57a2293684747da', 'Spreadsheet resmi UEQ dan UEQ-S yang diekspor kini keluar dengan semua hasil terhitung dan grafik terisi, bahkan di Tampilan Terproteksi Excel.'),
  (gen_random_uuid()::text, 'zh', 'a57a2293684747da', '导出的 UEQ 和 UEQ-S 官方表格现在会带着全部计算结果和填好的图表，即使在 Excel 的受保护的视图中也一样。'),
  (gen_random_uuid()::text, 'ja', 'a57a2293684747da', 'エクスポートした UEQ と UEQ-S の公式スプレッドシートに、計算済みのすべての結果と記入済みのグラフが入るようになりました。Excel の保護ビューでも表示されます。'),
  (gen_random_uuid()::text, 'ko', 'a57a2293684747da', '내보낸 UEQ 및 UEQ-S 공식 스프레드시트에 이제 계산된 모든 결과와 채워진 차트가 들어 있습니다. Excel의 제한된 보기에서도 마찬가지입니다.'),
  (gen_random_uuid()::text, 'en', '8ed88d2ae9f22320', 'When a page loads, a file is being generated or a form is being sent, a notice on the screen says what is happening.'),
  (gen_random_uuid()::text, 'es', '8ed88d2ae9f22320', 'Cuando una página carga, se genera un archivo o se envía un formulario, un aviso en la pantalla dice lo que está pasando.'),
  (gen_random_uuid()::text, 'de', '8ed88d2ae9f22320', 'Wenn eine Seite lädt, eine Datei erstellt oder ein Formular gesendet wird, zeigt ein Hinweis auf dem Bildschirm, was gerade passiert.'),
  (gen_random_uuid()::text, 'fr', '8ed88d2ae9f22320', 'Quand une page se charge, qu’un fichier est en cours de création ou qu’un formulaire est envoyé, un avis à l’écran indique ce qui se passe.'),
  (gen_random_uuid()::text, 'it', '8ed88d2ae9f22320', 'Quando una pagina si carica, un file viene generato o un modulo viene inviato, un avviso sullo schermo dice cosa sta succedendo.'),
  (gen_random_uuid()::text, 'nl', '8ed88d2ae9f22320', 'Als een pagina laadt, een bestand wordt gemaakt of een formulier wordt verzonden, laat een melding op het scherm zien wat er gebeurt.'),
  (gen_random_uuid()::text, 'da', '8ed88d2ae9f22320', 'Når en side indlæses, en fil oprettes eller en formular sendes, viser en meddelelse på skærmen, hvad der sker.'),
  (gen_random_uuid()::text, 'sv', '8ed88d2ae9f22320', 'När en sida laddas, en fil skapas eller ett formulär skickas visar ett meddelande på skärmen vad som händer.'),
  (gen_random_uuid()::text, 'nb', '8ed88d2ae9f22320', 'Når en side lastes inn, en fil lages eller et skjema sendes, viser et varsel på skjermen hva som skjer.'),
  (gen_random_uuid()::text, 'fi', '8ed88d2ae9f22320', 'Kun sivu latautuu, tiedostoa luodaan tai lomaketta lähetetään, näytön ilmoitus kertoo, mitä tapahtuu.'),
  (gen_random_uuid()::text, 'et', '8ed88d2ae9f22320', 'Kui leht laaditakse, faili luuakse või vormi saadetakse, ütleb ekraanil olev teade, mis toimub.'),
  (gen_random_uuid()::text, 'pl', '8ed88d2ae9f22320', 'Gdy strona się wczytuje, plik jest tworzony albo formularz jest wysyłany, komunikat na ekranie mówi, co się dzieje.'),
  (gen_random_uuid()::text, 'cs', '8ed88d2ae9f22320', 'Když se načítá stránka, vytváří soubor nebo odesílá formulář, upozornění na obrazovce říká, co se děje.'),
  (gen_random_uuid()::text, 'sk', '8ed88d2ae9f22320', 'Keď sa načítava stránka, vytvára súbor alebo odosiela formulár, upozornenie na obrazovke hovorí, čo sa deje.'),
  (gen_random_uuid()::text, 'sl', '8ed88d2ae9f22320', 'Ko se stran nalaga, se ustvarja datoteka ali pošilja obrazec, obvestilo na zaslonu pove, kaj se dogaja.'),
  (gen_random_uuid()::text, 'hr', '8ed88d2ae9f22320', 'Kad se stranica učitava, datoteka izrađuje ili obrazac šalje, obavijest na zaslonu govori što se događa.'),
  (gen_random_uuid()::text, 'bs', '8ed88d2ae9f22320', 'Kad se stranica učitava, datoteka pravi ili obrazac šalje, obavještenje na ekranu govori šta se dešava.'),
  (gen_random_uuid()::text, 'hu', '8ed88d2ae9f22320', 'Amikor egy oldal töltődik, egy fájl készül vagy egy űrlap elküldésre kerül, a képernyőn egy értesítés jelzi, mi történik.'),
  (gen_random_uuid()::text, 'bg', '8ed88d2ae9f22320', 'Когато страница се зарежда, файл се създава или формуляр се изпраща, известие на екрана казва какво се случва.'),
  (gen_random_uuid()::text, 'ru', '8ed88d2ae9f22320', 'Когда загружается страница, создаётся файл или отправляется форма, сообщение на экране говорит, что происходит.'),
  (gen_random_uuid()::text, 'el', '8ed88d2ae9f22320', 'Όταν μια σελίδα φορτώνει, ένα αρχείο δημιουργείται ή μια φόρμα αποστέλλεται, μια ειδοποίηση στην οθόνη λέει τι συμβαίνει.'),
  (gen_random_uuid()::text, 'tr', '8ed88d2ae9f22320', 'Bir sayfa yüklenirken, bir dosya oluşturulurken veya bir form gönderilirken ekrandaki bir uyarı ne olduğunu söyler.'),
  (gen_random_uuid()::text, 'ar', '8ed88d2ae9f22320', 'عندما تُحمَّل صفحة أو يُنشأ ملف أو يُرسَل نموذج، يوضح تنبيه على الشاشة ما يحدث.'),
  (gen_random_uuid()::text, 'he', '8ed88d2ae9f22320', 'כשדף נטען, קובץ נוצר או טופס נשלח, הודעה על המסך אומרת מה קורה.'),
  (gen_random_uuid()::text, 'fa', '8ed88d2ae9f22320', 'وقتی صفحه‌ای بارگذاری می‌شود، فایلی ساخته می‌شود یا فرمی فرستاده می‌شود، پیامی روی صفحه می‌گوید چه اتفاقی می‌افتد.'),
  (gen_random_uuid()::text, 'hi', '8ed88d2ae9f22320', 'जब कोई पेज लोड होता है, कोई फ़ाइल बन रही होती है या कोई फ़ॉर्म भेजा जा रहा होता है, तो स्क्रीन पर एक सूचना बताती है कि क्या हो रहा है।'),
  (gen_random_uuid()::text, 'mr', '8ed88d2ae9f22320', 'एखादे पेज लोड होताना, फाइल तयार होताना किंवा फॉर्म पाठवला जात असताना स्क्रीनवरील सूचना काय चालले आहे ते सांगते.'),
  (gen_random_uuid()::text, 'bn', '8ed88d2ae9f22320', 'কোনো পেজ লোড হলে, কোনো ফাইল তৈরি হলে বা কোনো ফর্ম পাঠানো হলে, স্ক্রিনের একটি বার্তা জানায় কী হচ্ছে।'),
  (gen_random_uuid()::text, 'ta', '8ed88d2ae9f22320', 'ஒரு பக்கம் ஏற்றப்படும்போதும், ஒரு கோப்பு உருவாக்கப்படும்போதும், ஒரு படிவம் அனுப்பப்படும்போதும், என்ன நடக்கிறது என்பதைத் திரையில் ஒரு அறிவிப்பு சொல்கிறது.'),
  (gen_random_uuid()::text, 'kn', '8ed88d2ae9f22320', 'ಪುಟ ಲೋಡ್ ಆಗುವಾಗ, ಫೈಲ್ ಸಿದ್ಧವಾಗುವಾಗ ಅಥವಾ ಫಾರ್ಮ್ ಕಳುಹಿಸುವಾಗ, ಏನಾಗುತ್ತಿದೆ ಎಂದು ಪರದೆಯ ಮೇಲಿನ ಸೂಚನೆ ಹೇಳುತ್ತದೆ.'),
  (gen_random_uuid()::text, 'th', '8ed88d2ae9f22320', 'เมื่อหน้ากำลังโหลด ไฟล์กำลังถูกสร้าง หรือแบบฟอร์มกำลังถูกส่ง ข้อความบนหน้าจอจะบอกว่าเกิดอะไรขึ้น'),
  (gen_random_uuid()::text, 'ms', '8ed88d2ae9f22320', 'Apabila halaman dimuatkan, fail sedang dijana atau borang sedang dihantar, satu notis pada skrin memberitahu apa yang sedang berlaku.'),
  (gen_random_uuid()::text, 'id', '8ed88d2ae9f22320', 'Saat halaman dimuat, file sedang dibuat, atau formulir sedang dikirim, pemberitahuan di layar menjelaskan apa yang sedang terjadi.'),
  (gen_random_uuid()::text, 'zh', '8ed88d2ae9f22320', '当页面正在加载、文件正在生成或表单正在提交时，屏幕上的提示会说明正在发生什么。'),
  (gen_random_uuid()::text, 'ja', '8ed88d2ae9f22320', 'ページの読み込み中、ファイルの作成中、フォームの送信中は、画面のお知らせで何が起きているかを表示します。'),
  (gen_random_uuid()::text, 'ko', '8ed88d2ae9f22320', '페이지를 불러오거나 파일을 만들거나 양식을 보내는 동안 화면의 안내가 무슨 일이 일어나는지 알려 줍니다.'),
  (gen_random_uuid()::text, 'en', 'b5b6366d76b2879b', 'Invitations and the notices from the bell arrive by email again, in your account''s language.'),
  (gen_random_uuid()::text, 'es', 'b5b6366d76b2879b', 'Las invitaciones y los avisos de la campana vuelven a llegar por correo electrónico, en el idioma de su cuenta.'),
  (gen_random_uuid()::text, 'de', 'b5b6366d76b2879b', 'Einladungen und die Hinweise der Glocke kommen wieder per E-Mail, in der Sprache Ihres Kontos.'),
  (gen_random_uuid()::text, 'fr', 'b5b6366d76b2879b', 'Les invitations et les avis de la cloche arrivent de nouveau par e-mail, dans la langue de votre compte.'),
  (gen_random_uuid()::text, 'it', 'b5b6366d76b2879b', 'Gli inviti e gli avvisi della campanella tornano ad arrivare via e-mail, nella lingua del Suo account.'),
  (gen_random_uuid()::text, 'nl', 'b5b6366d76b2879b', 'Uitnodigingen en de meldingen van de bel komen weer per e-mail, in de taal van uw account.'),
  (gen_random_uuid()::text, 'da', 'b5b6366d76b2879b', 'Invitationer og meddelelserne fra klokken kommer igen på e-mail, på din kontos sprog.'),
  (gen_random_uuid()::text, 'sv', 'b5b6366d76b2879b', 'Inbjudningar och aviseringarna från klockan kommer igen via e-post, på ditt kontos språk.'),
  (gen_random_uuid()::text, 'nb', 'b5b6366d76b2879b', 'Invitasjoner og varslene fra bjellen kommer igjen på e-post, på språket til kontoen din.'),
  (gen_random_uuid()::text, 'fi', 'b5b6366d76b2879b', 'Kutsut ja kellon ilmoitukset tulevat taas sähköpostiin, tilisi kielellä.'),
  (gen_random_uuid()::text, 'et', 'b5b6366d76b2879b', 'Kutsed ja kella teatised tulevad jälle e-postiga, sinu konto keeles.'),
  (gen_random_uuid()::text, 'pl', 'b5b6366d76b2879b', 'Zaproszenia i powiadomienia z dzwonka znowu przychodzą e-mailem, w języku Twojego konta.'),
  (gen_random_uuid()::text, 'cs', 'b5b6366d76b2879b', 'Pozvánky a upozornění ze zvonku zase chodí e-mailem, v jazyce vašeho účtu.'),
  (gen_random_uuid()::text, 'sk', 'b5b6366d76b2879b', 'Pozvánky a upozornenia zo zvončeka znova chodia e-mailom, v jazyku vášho účtu.'),
  (gen_random_uuid()::text, 'sl', 'b5b6366d76b2879b', 'Povabila in obvestila zvonca spet prihajajo po e-pošti, v jeziku vašega računa.'),
  (gen_random_uuid()::text, 'hr', 'b5b6366d76b2879b', 'Pozivnice i obavijesti sa zvona opet stižu e-poštom, na jeziku vašeg računa.'),
  (gen_random_uuid()::text, 'bs', 'b5b6366d76b2879b', 'Pozivnice i obavještenja sa zvona opet stižu e-poštom, na jeziku vašeg računa.'),
  (gen_random_uuid()::text, 'hu', 'b5b6366d76b2879b', 'A meghívók és a csengő értesítései újra megérkeznek e-mailben, a fiókja nyelvén.'),
  (gen_random_uuid()::text, 'bg', 'b5b6366d76b2879b', 'Поканите и известията от звънчето отново пристигат по имейл, на езика на вашия профил.'),
  (gen_random_uuid()::text, 'ru', 'b5b6366d76b2879b', 'Приглашения и уведомления из колокольчика снова приходят по e-mail, на языке вашей учётной записи.'),
  (gen_random_uuid()::text, 'el', 'b5b6366d76b2879b', 'Οι προσκλήσεις και οι ειδοποιήσεις του κουδουνιού φτάνουν ξανά με email, στη γλώσσα του λογαριασμού σας.'),
  (gen_random_uuid()::text, 'tr', 'b5b6366d76b2879b', 'Davetler ve zilin bildirimleri yeniden e-postayla, hesabınızın dilinde geliyor.'),
  (gen_random_uuid()::text, 'ar', 'b5b6366d76b2879b', 'عادت الدعوات وتنبيهات الجرس تصل عبر البريد الإلكتروني، بلغة حسابك.'),
  (gen_random_uuid()::text, 'he', 'b5b6366d76b2879b', 'ההזמנות וההתראות מהפעמון שוב מגיעות במייל, בשפה של החשבון שלך.'),
  (gen_random_uuid()::text, 'fa', 'b5b6366d76b2879b', 'دعوت‌ها و اعلان‌های زنگوله دوباره با ایمیل می‌رسند، به زبان حساب شما.'),
  (gen_random_uuid()::text, 'hi', 'b5b6366d76b2879b', 'आमंत्रण और घंटी की सूचनाएँ फिर से ईमेल से आती हैं, आपके खाते की भाषा में।'),
  (gen_random_uuid()::text, 'mr', 'b5b6366d76b2879b', 'आमंत्रणे आणि घंटीच्या सूचना पुन्हा ईमेलने येतात, तुमच्या खात्याच्या भाषेत.'),
  (gen_random_uuid()::text, 'bn', 'b5b6366d76b2879b', 'আমন্ত্রণ আর ঘণ্টার বিজ্ঞপ্তি আবার ইমেলে আসছে, আপনার অ্যাকাউন্টের ভাষায়।'),
  (gen_random_uuid()::text, 'ta', 'b5b6366d76b2879b', 'அழைப்புகளும் மணியின் அறிவிப்புகளும் மீண்டும் மின்னஞ்சலில் வருகின்றன, உங்கள் கணக்கின் மொழியில்.'),
  (gen_random_uuid()::text, 'kn', 'b5b6366d76b2879b', 'ಆಹ್ವಾನಗಳು ಮತ್ತು ಗಂಟೆಯ ಸೂಚನೆಗಳು ಮತ್ತೆ ಇಮೇಲ್‌ನಲ್ಲಿ ಬರುತ್ತಿವೆ, ನಿಮ್ಮ ಖಾತೆಯ ಭಾಷೆಯಲ್ಲಿ.'),
  (gen_random_uuid()::text, 'th', 'b5b6366d76b2879b', 'คำเชิญและการแจ้งเตือนจากกระดิ่งกลับมาส่งทางอีเมลแล้ว ในภาษาของบัญชีคุณ'),
  (gen_random_uuid()::text, 'ms', 'b5b6366d76b2879b', 'Jemputan dan pemberitahuan loceng kini sampai semula melalui e-mel, dalam bahasa akaun anda.'),
  (gen_random_uuid()::text, 'id', 'b5b6366d76b2879b', 'Undangan dan pemberitahuan dari lonceng kembali dikirim lewat email, dalam bahasa akun Anda.'),
  (gen_random_uuid()::text, 'zh', 'b5b6366d76b2879b', '邀请和铃铛里的通知又会通过电子邮件发送，使用您账户的语言。'),
