  (gen_random_uuid()::text, 'ta', '9023f4b5d9cf8671', 'அறிவிப்புகளைத் திறக்கவும்'),
  (gen_random_uuid()::text, 'kn', '9023f4b5d9cf8671', 'ಅಧಿಸೂಚನೆಗಳನ್ನು ತೆರೆಯಿರಿ'),
