  (gen_random_uuid()::text, 'ko', '9023f4b5d9cf8671', '알림 열기'),
  (gen_random_uuid()::text, 'en', '30224541198875a0', 'The invitation also appears in the notifications bell, at the top of the tool, with Accept and Decline.'),
  (gen_random_uuid()::text, 'es', '30224541198875a0', 'La invitación también aparece en la campana de notificaciones, en la parte superior de la herramienta, con Aceptar y Rechazar.'),
  (gen_random_uuid()::text, 'de', '30224541198875a0', 'Die Einladung erscheint auch in der Benachrichtigungsglocke oben im Tool, mit Annehmen und Ablehnen.'),
  (gen_random_uuid()::text, 'fr', '30224541198875a0', 'L’invitation apparaît aussi dans la cloche des notifications, en haut de l’outil, avec Accepter et Refuser.'),
  (gen_random_uuid()::text, 'it', '30224541198875a0', 'L’invito compare anche nella campanella delle notifiche, in alto nello strumento, con Accetta e Rifiuta.'),
  (gen_random_uuid()::text, 'nl', '30224541198875a0', 'De uitnodiging staat ook bij de meldingenbel, bovenaan in de tool, met Accepteren en Weigeren.'),
  (gen_random_uuid()::text, 'da', '30224541198875a0', 'Invitationen vises også i notifikationsklokken øverst i værktøjet, med Accepter og Afvis.'),
  (gen_random_uuid()::text, 'sv', '30224541198875a0', 'Inbjudan syns också i aviseringsklockan högst upp i verktyget, med Acceptera och Avvisa.'),
  (gen_random_uuid()::text, 'nb', '30224541198875a0', 'Invitasjonen vises også i varselbjellen øverst i verktøyet, med Godta og Avslå.'),
  (gen_random_uuid()::text, 'fi', '30224541198875a0', 'Kutsu näkyy myös ilmoituskellossa työkalun yläreunassa, ja siinä on Hyväksy ja Hylkää.'),
  (gen_random_uuid()::text, 'et', '30224541198875a0', 'Kutse on näha ka teavituste kellas tööriista ülaosas, koos nuppudega Nõustu ja Keeldu.'),
  (gen_random_uuid()::text, 'pl', '30224541198875a0', 'Zaproszenie widać też w dzwonku powiadomień u góry narzędzia, z przyciskami Zaakceptuj i Odrzuć.'),
  (gen_random_uuid()::text, 'cs', '30224541198875a0', 'Pozvánka se objeví i ve zvonku oznámení nahoře v nástroji, s tlačítky Přijmout a Odmítnout.'),
  (gen_random_uuid()::text, 'sk', '30224541198875a0', 'Pozvánka sa zobrazí aj v zvončeku upozornení hore v nástroji, s tlačidlami Prijať a Odmietnuť.'),
  (gen_random_uuid()::text, 'sl', '30224541198875a0', 'Povabilo se prikaže tudi v zvoncu obvestil na vrhu orodja, z gumboma Sprejmite in Zavrnite.'),
  (gen_random_uuid()::text, 'hr', '30224541198875a0', 'Pozivnica se pojavljuje i na zvonu obavijesti, na vrhu alata, s gumbima Prihvati i Odbij.'),
  (gen_random_uuid()::text, 'bs', '30224541198875a0', 'Pozivnica se pojavljuje i na zvonu obavještenja, na vrhu alata, s dugmadima Prihvati i Odbij.'),
  (gen_random_uuid()::text, 'hu', '30224541198875a0', 'A meghívó az eszköz tetején lévő értesítési csengőnél is megjelenik, Elfogadás és Elutasítás gombokkal.'),
  (gen_random_uuid()::text, 'bg', '30224541198875a0', 'Поканата се появява и в звънчето за известия горе в инструмента, с бутоните Приемане и Отхвърляне.'),
  (gen_random_uuid()::text, 'ru', '30224541198875a0', 'Приглашение также появляется в колокольчике уведомлений вверху инструмента, с кнопками Принять и Отклонить.'),
  (gen_random_uuid()::text, 'el', '30224541198875a0', 'Η πρόσκληση εμφανίζεται και στο κουδούνι των ειδοποιήσεων, στο πάνω μέρος του εργαλείου, με Αποδοχή και Απόρριψη.'),
  (gen_random_uuid()::text, 'tr', '30224541198875a0', 'Davet, aracın üst kısmındaki bildirim zilinde de Kabul et ve Reddet ile görünür.'),
  (gen_random_uuid()::text, 'ar', '30224541198875a0', 'تظهر الدعوة أيضًا في جرس الإشعارات أعلى الأداة، مع قبول ورفض.'),
  (gen_random_uuid()::text, 'he', '30224541198875a0', 'ההזמנה מופיעה גם בפעמון ההתראות בראש הכלי, עם קבלה ודחייה.'),
  (gen_random_uuid()::text, 'fa', '30224541198875a0', 'دعوت در زنگولهٔ اعلان‌ها، بالای ابزار، هم با پذیرفتن و رد کردن نمایش داده می‌شود.'),
  (gen_random_uuid()::text, 'hi', '30224541198875a0', 'आमंत्रण टूल में सबसे ऊपर सूचनाओं की घंटी में भी दिखता है, स्वीकारें और अस्वीकार करें के साथ।'),
  (gen_random_uuid()::text, 'mr', '30224541198875a0', 'आमंत्रण टूलच्या वरच्या भागातील सूचनांच्या घंटीतही स्वीकारा आणि नाकारा यांसह दिसते.'),
  (gen_random_uuid()::text, 'bn', '30224541198875a0', 'আমন্ত্রণটি টুলের উপরের দিকে বিজ্ঞপ্তির ঘণ্টাতেও গ্রহণ করুন ও প্রত্যাখ্যান করুনসহ দেখা যায়।'),
  (gen_random_uuid()::text, 'ta', '30224541198875a0', 'அழைப்பு கருவியின் மேலே உள்ள அறிவிப்பு மணியிலும் ஏற்கவும், நிராகரிக்கவும் என்பவற்றுடன் தெரியும்.'),
